import sys
from collections import Counter

def find_divisors(n):
    divisors = set()
    for i in range(1, int(n**0.5) + 1):
        if n % i == 0:
            divisors.add(i)
            divisors.add(n // i)
    return sorted(divisors)

def find_x_y(divisors):
    counter = Counter(divisors)
    unique_divisors = list(counter.keys())

    for i in range(len(unique_divisors)):
        for j in range(i, len(unique_divisors)):
            x = unique_divisors[i]
            y = unique_divisors[j]
            x_divs = find_divisors(x)
            y_divs = find_divisors(y)
            combined_divs = x_divs + y_divs
            combined_counter = Counter(combined_divs)

            if combined_counter == counter:
                return x, y

def main():
    import sys
    input = sys.stdin.read
    data = input().split()

    n = int(data[0])
    divisors = list(map(int, data[1:]))

    x, y = find_x_y(divisors)
    print(x, y)

if __name__ == "__main__":
    main()
